import{_ as e,o,c as r,a0 as n}from"./chunks/framework.B7o6dWmz.js";const g=JSON.parse('{"title":"NetonAPI vs new-api / one-api","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"compare.md","filePath":"compare.md","lastUpdated":1793979958000}'),d={name:"compare.md"};function a(s,t,i,p,c,l){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="netonapi-vs-new-api-one-api" tabindex="-1">NetonAPI vs new-api / one-api <a class="header-anchor" href="#netonapi-vs-new-api-one-api" aria-label="Permalink to &quot;NetonAPI vs new-api / one-api&quot;">​</a></h1><p>NetonAPI is not a fork of one-api / new-api. It was designed from the <strong>operator&#39;s</strong> side: prices are anchored to the official price, every channel carries its real cost, a price that would lose money cannot be saved, and every charge reconciles as &quot;unit price × tokens&quot;. The table compares it with the two most widely used open-source relay projects.</p><table tabindex="0"><thead><tr><th>Capability</th><th>NetonAPI 1.0</th><th><a href="https://github.com/QuantumNous/new-api" target="_blank" rel="noreferrer">new-api</a></th><th><a href="https://github.com/songquanpeng/one-api" target="_blank" rel="noreferrer">one-api</a></th></tr></thead><tbody><tr><td><strong>Pricing</strong></td><td>Anchored to the official price: sale = official × markup; groups and individual users can get &quot;N% of official&quot; per model</td><td>Ratio system: model ratio × completion ratio × group ratio; fixed per-request price; tiered expression pricing</td><td>Ratio system: group ratio × model ratio × completion ratio</td></tr><tr><td><strong>Per-user, per-model negotiated price</strong></td><td>Yes (&quot;Negotiated pricing&quot;: find a user, discount model by model, in bulk)</td><td>Via user group ratio</td><td>Via user group ratio</td></tr><tr><td><strong>Real channel cost</strong></td><td>Each channel records its cost (official × discount / upstream pricing API / per-model manual); abnormal jumps wait for approval</td><td>Not covered in public docs</td><td>Not covered in public docs</td></tr><tr><td><strong>Margin protection</strong></td><td>A price below channel cost <strong>cannot be saved</strong>; price health check shows the worst margin per group × channel; profit dashboard</td><td>Not covered in public docs</td><td>Not covered in public docs</td></tr><tr><td><strong>Official price upkeep</strong></td><td>Scheduled sync from a price source; changes held for operator approval; full price history</td><td>Ratio settings, can sync upstream ratios</td><td>Built-in default ratios, edited by hand</td></tr><tr><td><strong>Charge vs. displayed price</strong></td><td>Charge = tokens × the unit price the user sees (rounded per item); console, price list and bill agree; unknown cache price bills at input price</td><td>Pre-deduct, then settle the difference</td><td>Pre-deduct, then settle</td></tr><tr><td><strong>Ledger</strong></td><td>Two-phase reserve → settle, crash-recoverable, anomalies go to a manual review queue; price snapshot frozen per request</td><td>Pre-deduct + post-settle</td><td>Pre-deduct + post-settle</td></tr><tr><td><strong>Billing group</strong></td><td>Decided by the API key; operators can pin a key to a group (dedicated route / special price)</td><td>User group, selectable per token</td><td>User and channel groups</td></tr><tr><td><strong>API key handling</strong></td><td>Shown once at creation, only a hash is stored; upstream keys encrypted at rest</td><td>Viewable and copyable in the list</td><td>Viewable and copyable in the list</td></tr><tr><td><strong>Inbound protocols</strong></td><td>Native OpenAI (Chat, Responses), Anthropic and Gemini endpoints, <strong>converted in any direction</strong> (tools, images, thinking, cache usage preserved)</td><td>Conversion among OpenAI Chat, Responses, Anthropic and Gemini; Realtime WebSocket</td><td>Unified to the OpenAI format</td></tr><tr><td><strong>Upstream types</strong></td><td>OpenAI-compatible, Azure OpenAI, Anthropic, Gemini, AWS Bedrock, Vertex AI</td><td>Dozens, domestic and international</td><td>30+ providers</td></tr><tr><td><strong>Channel failover</strong></td><td>Priority + weight; automatic failover; an upstream &quot;model not found&quot; moves to the next channel instead of failing the user; key auto-disable and cooldown; scheduled probes</td><td>Priority + weight, retries, channel affinity, multiple keys</td><td>Load balancing, retries, auto-disable by success rate</td></tr><tr><td><strong>Task APIs</strong> (Midjourney, video…)</td><td>Not yet</td><td>Yes (JavaScript plugins)</td><td>No</td></tr><tr><td><strong>Operator permissions</strong></td><td>Menu- and button-level permissions; preset gateway ops / finance / support / read-only roles</td><td>Fine-grained permissions</td><td>Admin / root</td></tr><tr><td><strong>User sign-in</strong></td><td>Username and password, SMS code (needs an SMS provider), email password reset</td><td>OAuth / OIDC, passkeys, 2FA</td><td>Email, GitHub, Feishu, WeChat</td></tr><tr><td><strong>Top-up</strong></td><td>Manual top-up by admins, redemption codes, online payment (Alipay, aggregators, pluggable); payment secrets write-only</td><td>Redemption codes, EPay, Stripe, subscriptions</td><td>Redemption codes, top-up link</td></tr><tr><td><strong>Build and deploy</strong></td><td>Kotlin/Native <strong>single native executable</strong>, no JVM at runtime; PostgreSQL (Redis optional)</td><td>Go binary / Docker; SQLite / MySQL / PostgreSQL</td><td>Go binary / Docker; SQLite / MySQL</td></tr><tr><td><strong>Status</strong></td><td>1.0.0</td><td>Releasing continuously (v1.0.0-rc series)</td><td>Latest release v0.6.10 (2025-02), none since</td></tr></tbody></table><p>The new-api and one-api columns are compiled from their public READMEs and documentation (2026-11). &quot;Not covered in public docs&quot; means we found no description, not that the feature certainly does not exist; check their latest releases for details.</p><p>Want to see NetonAPI running? Sign up at <a href="https://neton.cloud" target="_blank" rel="noreferrer">Neton Cloud</a>.</p>',5)])])}const h=e(d,[["render",a]]);export{g as __pageData,h as default};
